    @Test
    void unload_releasesCompartmentKeepsHistoryAndAllowsReload() throws Exception {
        String pallet = "PL-UL-" + unique();
        createPallet(pallet, 2, "CK-PC", 201);
        String b1 = "BK-U1-" + unique();
